function student_fields(){return ['code','full_name','dob','gender','place_of_birth','ethnicity','religion','nationality','citizen_id','health_insurance_no','social_insurance_no','permanent_address','current_address','hamlet','commune','district','province','father_name','father_dob','father_job','father_phone','father_address','mother_name','mother_dob','mother_job','mother_phone','mother_address','guardian_name','guardian_relation','guardian_phone','guardian_address','household_head','household_code','household_type','class_id','school_year','admission_date','previous_school','enrollment_type','status','transfer_date','transfer_destination','policy_category','poor_household','near_poor_household','disability','disability_type','boarding_status','priority_status','notes'];}
if($page==='save_student'&&$_SERVER['REQUEST_METHOD']==='POST'){require_role(['admin','teacher']);$id=(int)val('id',0);$fields=student_fields();$data=[];$sets=[];$params=[];foreach($fields as $f){$v=val($f);if(in_array($f,['poor_household','near_poor_household','disability']))$v=isset($_POST[$f])?1:0;if(in_array($f,['class_id'])&&$v==='')$v=null;$data[$f]=$v;if($f!=='school_year'&&$f!=='status'&&$f!=='code'&&$f!=='full_name'){} } if(!$data['code']||!$data['full_name']){flash('danger','Mã học sinh và họ tên là bắt buộc.');redir('index.php?page=students&edit='.$id);} try{if($id){foreach($fields as $f){$sets[]="`$f`=?";$params[]=$data[$f];}$params[]=$id;q('UPDATE students SET '.implode(',',$sets).' WHERE id=?',$params);flash('success','Đã cập nhật toàn bộ hồ sơ học sinh.');}else{$cols=implode(',',array_map(fn($x)=>"`$x`",$fields));$marks=implode(',',array_fill(0,count($fields),'?'));q("INSERT INTO students($cols) VALUES($marks)",array_values($data));flash('success','Đã thêm hồ sơ học sinh vào cơ sở dữ liệu.');}}catch(Throwable $e){flash('danger','Không lưu được: '.$e->getMessage());}redir('index.php?page=students');}
if($page==='delete_student'&&$_SERVER['REQUEST_METHOD']==='POST'){require_role('admin');$id=(int)post('id',0);if($id<=0){flash('danger','Không xác định được hồ sơ cần xóa.');redir('index.php?page=students');}try{$pdo=db();$pdo->beginTransaction();/* Xóa dữ liệu nghiệp vụ liên quan trước để tương thích cả với database cũ chưa khai báo ON DELETE CASCADE. */q('DELETE FROM student_documents WHERE student_id=?',[$id]);q('DELETE FROM attendance WHERE student_id=?',[$id]);q('DELETE FROM assessments WHERE student_id=?',[$id]);$st=q('DELETE FROM students WHERE id=?',[$id]);if($st->rowCount()===0){throw new RuntimeException('Hồ sơ học sinh không tồn tại hoặc đã được xóa.');}$pdo->commit();flash('success','Đã xóa hồ sơ học sinh và các dữ liệu liên quan.');}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('danger','Không thể xóa hồ sơ: '.$e->getMessage());}redir('index.php?page=students');}
if($page==='save_teacher'&&$_SERVER['REQUEST_METHOD']==='POST'){require_role('admin');q('INSERT INTO teachers(code,full_name,gender,dob,phone,email,subject,address,qualification,position_name,personnel_type) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[post('code'),post('full_name'),post('gender'),val('dob')?:null,post('phone'),post('email'),post('subject'),post('address'),post('qualification'),post('position_name'),post('personnel_type','Giáo viên')]);flash('success','Đã thêm giáo viên.');redir('index.php?page=teachers');}
if($page==='save_class'&&$_SERVER['REQUEST_METHOD']==='POST'){require_role('admin');q('INSERT INTO classes(code,name,grade,school_year,teacher_id,room,session_name,capacity) VALUES(?,?,?,?,?,?,?,?)',[post('code'),post('name'),(int)val('grade'),post('school_year',SCHOOL_YEAR),val('teacher_id')?:null,post('room'),post('session_name'),(int)val('capacity',35)]);flash('success','Đã thêm lớp học.');redir('index.php?page=classes');}
if($page==='save_attendance'&&$_SERVER['REQUEST_METHOD']==='POST'){require_role(['admin','teacher']);$date=val('date');foreach($_POST['status']??[] as $sid=>$st){q('INSERT INTO attendance(student_id,date,status,note) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),note=VALUES(note)',[(int)$sid,$date,$st,post('note_'.$sid)]);}flash('success','Đã lưu điểm danh ngày '.date('d/m/Y',strtotime($date)));redir('index.php?page=attendance&date='.urlencode($date));}
if($page==='save_assessment'&&$_SERVER['REQUEST_METHOD']==='POST'){require_role(['admin','teacher']);q('INSERT INTO assessments(student_id,subject_id,period,result,comment) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE result=VALUES(result),comment=VALUES(comment)',[(int)val('student_id'),(int)val('subject_id'),post('period'),post('result'),post('comment')]);flash('success','Đã lưu đánh giá.');redir('index.php?page=assessments&student_id='.(int)val('student_id'));}
if($page==='save_document'&&$_SERVER['REQUEST_METHOD']==='POST'){require_role(['admin','teacher']);q('INSERT INTO student_documents(student_id,document_type,document_no,issue_date,issuer,note) VALUES(?,?,?,?,?,?)',[(int)val('student_id'),post('document_type'),post('document_no'),val('issue_date')?:null,post('issuer'),post('note')]);flash('success','Đã thêm giấy tờ vào hồ sơ.');redir('index.php?page=documents&student_id='.(int)val('student_id'));}
