if($page==='dashboard'){layout_head('Tổng quan');$sc=one('SELECT COUNT(*) n FROM students')['n'];$cc=one('SELECT COUNT(*) n FROM classes')['n'];$tc=one('SELECT COUNT(*) n FROM teachers')['n'];$tg=one("SELECT COUNT(*) n FROM teachers WHERE personnel_type='Giáo viên'")['n'];$nv=one("SELECT COUNT(*) n FROM teachers WHERE personnel_type='Nhân viên'")['n'];$doc=one('SELECT COUNT(*) n FROM student_documents')['n'];$notice=one('SELECT COUNT(*) n FROM announcements')['n'];?><div class="page-title"><div><h1>Tổng quan hệ thống</h1><p>Quản lý hồ sơ học sinh năm học <?=e(SCHOOL_YEAR)?></p></div></div><div class="cards"><div class="card stat"><span>👨‍🎓</span><div><small>Học sinh</small><strong><?=$sc?></strong></div></div><div class="card stat"><span>🏫</span><div><small>Lớp học</small><strong><?=$cc?></strong></div></div><div class="card stat"><span>👩‍🏫</span><div><small>CB, giáo viên, nhân viên</small><strong><?=$tc?></strong></div></div><div class="card stat"><span>📁</span><div><small>Giấy tờ hồ sơ</small><strong><?=$doc?></strong></div></div><div class="card stat"><span>📢</span><div><small>Thông báo</small><strong><?=$notice?></strong></div></div></div><section class="card"><h2>Quy trình giáo vụ</h2><div class="quick"><a href="index.php?page=students">① Tiếp nhận và cập nhật hồ sơ học sinh</a><a href="index.php?page=classes">② Xếp lớp, cập nhật năm học</a><a href="index.php?page=attendance">③ Theo dõi chuyên cần</a><a href="index.php?page=assessments">④ Theo dõi đánh giá học tập</a><a href="index.php?page=documents">⑤ Quản lý giấy tờ hồ sơ</a></div></section><?php layout_foot();exit;}

if($page==='students'){layout_head('Hồ sơ học sinh');$qstr=$_GET['q']??'';$class=(int)($_GET['class_id']??0);$where=[];$p=[];if($qstr){$where[]='(s.full_name LIKE ? OR s.code LIKE ? OR s.citizen_id LIKE ? OR s.father_phone LIKE ? OR s.mother_phone LIKE ?)';array_push($p,"%$qstr%","%$qstr%","%$qstr%","%$qstr%","%$qstr%");}if($class){$where[]='s.class_id=?';$p[]=$class;}$sql='SELECT s.*,c.name class_name FROM students s LEFT JOIN classes c ON c.id=s.class_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY s.id DESC LIMIT 500';$rows=all($sql,$p);$edit=isset($_GET['edit'])?one('SELECT * FROM students WHERE id=?',[(int)$_GET['edit']]):null;$classes=all('SELECT * FROM classes ORDER BY grade,name');?><div class="page-title"><div><h1>Hồ sơ học sinh</h1><p>Nhập và quản lý hồ sơ phục vụ công tác giáo vụ, thống kê và phổ cập.</p></div><?php if(in_array($role,['admin','teacher'])):?><a class="btn primary" href="#form">+ Nhập hồ sơ học sinh</a><?php endif;?></div><section class="card"><form class="search" method="get"><input type="hidden" name="page" value="students"><input name="q" placeholder="Mã HS, họ tên, CCCD, SĐT phụ huynh..." value="<?=e($qstr)?>"><select name="class_id"><option value="0">Tất cả lớp</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$class==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><button class="btn">Tra cứu</button></form><div class="table-wrap"><table><tr><th>STT</th><th>Mã HS</th><th>Họ và tên</th><th>Ngày sinh</th><th>Giới tính</th><th>Lớp</th><th>Cha/Mẹ</th><th>Trạng thái</th><th>Thao tác</th></tr><?php foreach($rows as $i=>$s):?><tr><td><?=$i+1?></td><td><b><?=e($s['code'])?></b></td><td><?=e($s['full_name'])?></td><td><?=e($s['dob']?date('d/m/Y',strtotime($s['dob'])):'')?></td><td><?=e($s['gender'])?></td><td><?=e($s['class_name']??'Chưa xếp')?></td><td><?=e($s['mother_name']?:$s['father_name'])?></td><td><span class="badge success"><?=e($s['status'])?></span></td><td><a class="link" href="index.php?page=student_view&id=<?=$s['id']?>">Hồ sơ</a><?php if(in_array($role,['admin','teacher'])):?><a class="link" href="index.php?page=students&edit=<?=$s['id']?>#form">Sửa</a><?php endif;?><?php if($role==='admin'):?><form method="post" action="index.php?page=delete_student" style="display:inline" onsubmit="return confirm('Xóa hồ sơ này? Dữ liệu chuyên cần, đánh giá và giấy tờ liên quan cũng sẽ được xóa.');"><input type="hidden" name="id" value="<?=$s['id']?>"><button type="submit" class="link danger-text" style="border:0;background:none;padding:0;cursor:pointer;font:inherit;">Xóa</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section><?php if(in_array($role,['admin','teacher'])):?><section class="card" id="form"><h2><?=$edit?'Cập nhật':'Nhập mới'?> hồ sơ học sinh</h2><p class="muted">Các nhóm thông tin dưới đây được thiết kế theo công việc quản lý hồ sơ, thống kê và hỗ trợ giáo viên của giáo vụ.</p><form class="form-grid" method="post" action="index.php?page=save_student"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><h3 class="fullrow">A. Thông tin nhân thân</h3><?php $fields=[['code','Mã học sinh','text',1],['full_name','Họ và tên','text',1],['dob','Ngày sinh','date'],['gender','Giới tính','select',['Nam','Nữ','Khác']],['place_of_birth','Nơi sinh','text'],['ethnicity','Dân tộc','text'],['religion','Tôn giáo','text'],['nationality','Quốc tịch','text'],['citizen_id','Số CCCD/định danh','text'],['health_insurance_no','Mã thẻ BHYT','text'],['social_insurance_no','Mã số BHXH','text']];foreach($fields as $f):?><label><?=e($f[1])?><?php if($f[2]==='select'):?><select name="<?=$f[0]?>"><?php foreach($f[3] as $o):?><option <?=($edit[$f[0]]??'')===$o?'selected':''?>><?=$o?></option><?php endforeach;?></select><?php else:?><input <?=$f[3]??''?'required':''?> type="<?=$f[2]?>" name="<?=$f[0]?>" value="<?=e($edit[$f[0]]??'')?>"><?php endif;?></label><?php endforeach;?><h3 class="fullrow">B. Địa chỉ và hộ khẩu</h3><?php foreach([['permanent_address','Địa chỉ thường trú'],['current_address','Nơi ở hiện nay'],['hamlet','Ấp/khóm'],['commune','Xã/phường'],['district','Huyện/thành phố'],['province','Tỉnh/thành phố'],['household_head','Chủ hộ'],['household_code','Mã hộ gia đình'],['household_type','Loại hộ']] as $f):?><label><?=e($f[1])?><input name="<?=$f[0]?>" value="<?=e($edit[$f[0]]??'')?>"></label><?php endforeach;?><h3 class="fullrow">C. Cha, mẹ và người giám hộ</h3><?php foreach([['father_name','Họ tên cha'],['father_dob','Năm sinh cha'],['father_job','Nghề nghiệp cha'],['father_phone','SĐT cha'],['father_address','Địa chỉ cha'],['mother_name','Họ tên mẹ'],['mother_dob','Năm sinh mẹ'],['mother_job','Nghề nghiệp mẹ'],['mother_phone','SĐT mẹ'],['mother_address','Địa chỉ mẹ'],['guardian_name','Người giám hộ'],['guardian_relation','Quan hệ với HS'],['guardian_phone','SĐT người giám hộ'],['guardian_address','Địa chỉ người giám hộ']] as $f):?><label><?=e($f[1])?><input name="<?=$f[0]?>" value="<?=e($edit[$f[0]]??'')?>"></label><?php endforeach;?><h3 class="fullrow">D. Thông tin nhập học – chuyển trường – lớp</h3><label>Lớp<select name="class_id"><option value="">-- Chưa xếp lớp --</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=($edit['class_id']??'')==$c['id']?'selected':''?>><?=e($c['name'])?> – Khối <?=$c['grade']?></option><?php endforeach;?></select></label><label>Năm học<input name="school_year" value="<?=e($edit['school_year']??SCHOOL_YEAR)?>"></label><label>Ngày nhập học<input type="date" name="admission_date" value="<?=e($edit['admission_date']??'')?>"></label><label>Trường chuyển đến từ<input name="previous_school" value="<?=e($edit['previous_school']??'')?>"></label><label>Hình thức tuyển sinh<input name="enrollment_type" value="<?=e($edit['enrollment_type']??'')?>" placeholder="Tuyển mới / chuyển đến..."></label><label>Trạng thái<select name="status"><?php foreach(['Đang học','Chuyển đi','Nghỉ học','Hoàn thành tiểu học'] as $o):?><option <?=($edit['status']??'Đang học')===$o?'selected':''?>><?=$o?></option><?php endforeach;?></select></label><label>Ngày chuyển đi<input type="date" name="transfer_date" value="<?=e($edit['transfer_date']??'')?>"></label><label>Nơi chuyển đến<input name="transfer_destination" value="<?=e($edit['transfer_destination']??'')?>"></label><h3 class="fullrow">E. Chính sách, phổ cập và hoàn cảnh</h3><label>Diện chính sách<input name="policy_category" value="<?=e($edit['policy_category']??'')?>" placeholder="Hộ nghèo, khuyết tật, con chính sách..." ></label><label>Diện bán trú<input name="boarding_status" value="<?=e($edit['boarding_status']??'')?>"></label><label>Đối tượng ưu tiên<input name="priority_status" value="<?=e($edit['priority_status']??'')?>"></label><label>Hộ nghèo<input type="checkbox" name="poor_household" value="1" <?=!empty($edit['poor_household'])?'checked':''?>></label><label>Hộ cận nghèo<input type="checkbox" name="near_poor_household" value="1" <?=!empty($edit['near_poor_household'])?'checked':''?>></label><label>Khuyết tật<input type="checkbox" name="disability" value="1" <?=!empty($edit['disability'])?'checked':''?>></label><label>Loại khuyết tật<input name="disability_type" value="<?=e($edit['disability_type']??'')?>"></label><label class="fullrow">Ghi chú nghiệp vụ<textarea name="notes" rows="4" placeholder="Ghi chú bổ sung, tình trạng hồ sơ, lưu ý khi thống kê..."> <?=e($edit['notes']??'')?></textarea></label><div class="form-actions fullrow"><button class="btn primary">💾 Lưu hồ sơ</button><?php if($edit):?><a class="btn" href="index.php?page=students">Hủy chỉnh sửa</a><?php endif;?></div></form></section><?php endif;?><?php layout_foot();exit;}
