if($page==='classes'){layout_head('Lớp học');$rows=all('SELECT c.*,t.full_name teacher_name,(SELECT COUNT(*) FROM students s WHERE s.class_id=c.id) student_count FROM classes c LEFT JOIN teachers t ON t.id=c.teacher_id ORDER BY c.grade,c.name');$teachers=all("SELECT * FROM teachers WHERE active=1 AND personnel_type='Giáo viên' ORDER BY full_name");?><div class="page-title"><div><h1>Quản lý lớp học</h1><p>Xếp lớp và theo dõi sĩ số theo năm học.</p></div></div><section class="card"><div class="table-wrap"><table><tr><th>Mã</th><th>Lớp</th><th>Khối</th><th>Năm học</th><th>Chủ nhiệm</th><th>Phòng</th><th>Sĩ số</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['code'])?></td><td><b><?=e($r['name'])?></b></td><td><?=$r['grade']?></td><td><?=e($r['school_year'])?></td><td><?=e($r['teacher_name']??'Chưa phân công')?></td><td><?=e($r['room'])?></td><td><?=$r['student_count']?>/<?=$r['capacity']?></td></tr><?php endforeach;?></table></div></section><?php if($role==='admin'):?><section class="card"><h2>Thêm lớp học</h2><form class="form-grid" method="post" action="index.php?page=save_class"><label>Mã lớp<input required name="code" placeholder="101"></label><label>Tên lớp<input required name="name" placeholder="1/1"></label><label>Khối<select name="grade"><?php for($i=1;$i<=5;$i++):?><option><?=$i?></option><?php endfor;?></select></label><label>Năm học<input name="school_year" value="<?=e(SCHOOL_YEAR)?>"></label><label>Giáo viên chủ nhiệm<select name="teacher_id"><option value="">-- Chưa phân công --</option><?php foreach($teachers as $t):?><option value="<?=$t['id']?>"><?=e($t['full_name'])?></option><?php endforeach;?></select></label><label>Phòng học<input name="room"></label><label>Buổi học<input name="session_name" value="Cả ngày"></label><label>Sĩ số tối đa<input type="number" name="capacity" value="35"></label><div><button class="btn primary">Lưu lớp</button></div></form></section><?php endif;?><?php layout_foot();exit;}
if($page==='teachers'){require_role('admin');layout_head('Giáo viên');$rows=all('SELECT * FROM teachers ORDER BY full_name');?><div class="page-title"><div><h1>Quản lý cán bộ, giáo viên và nhân viên</h1><p>Quản lý 31 giáo viên và 07 nhân viên phục vụ công tác nhà trường.</p></div></div><section class="card"><div class="table-wrap"><table><tr><th>Mã</th><th>Họ tên</th><th>Loại nhân sự</th><th>Giới tính</th><th>Ngày sinh</th><th>Điện thoại</th><th>Email</th><th>Môn/lĩnh vực</th><th>Trình độ</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['code'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['personnel_type']??'Giáo viên')?></td><td><?=e($r['gender'])?></td><td><?=e($r['dob'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['email'])?></td><td><?=e($r['subject'])?></td><td><?=e($r['qualification'])?></td></tr><?php endforeach;?></table></div></section><section class="card"><h2>Nhập hồ sơ giáo viên</h2><form class="form-grid" method="post" action="index.php?page=save_teacher"><label>Mã giáo viên<input required name="code"></label><label>Họ và tên<input required name="full_name"></label><label>Giới tính<select name="gender"><option>Nam</option><option>Nữ</option></select></label><label>Ngày sinh<input type="date" name="dob"></label><label>Số điện thoại<input name="phone"></label><label>Email<input type="email" name="email"></label><label>Môn/ lĩnh vực<input name="subject"></label><label>Địa chỉ<input name="address"></label><label>Trình độ<input name="qualification" placeholder="Đại học"></label><label>Chức vụ<input name="position_name" placeholder="Giáo viên/Chủ nhiệm"></label><div><button class="btn primary">Lưu giáo viên</button></div></form></section><?php layout_foot();exit;}
if($page==='attendance'){require_role(['admin','teacher']);layout_head('Chuyên cần');$date=val('date',$_GET['date']??date('Y-m-d'));$class=(int)($_GET['class_id']??0);$classes=all('SELECT * FROM classes ORDER BY grade,name');$sql='SELECT s.*,c.name class_name FROM students s LEFT JOIN classes c ON c.id=s.class_id'.($class?' WHERE s.class_id=?':'').' ORDER BY c.grade,c.name,s.full_name';$students=all($sql,$class?[$class]:[]);$att=[];foreach(all('SELECT * FROM attendance WHERE date=?',[$date]) as $a)$att[$a['student_id']]=$a;?><div class="page-title"><div><h1>Điểm danh học sinh</h1><p>Nhập chuyên cần theo ngày, lớp và từng học sinh.</p></div></div><section class="card"><form class="search"><input type="hidden" name="page" value="attendance"><label>Ngày<input type="date" name="date" value="<?=e($date)?>"></label><select name="class_id"><option value="0">Tất cả lớp</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$class==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><button class="btn">Xem</button></form><form method="post" action="index.php?page=save_attendance"><input type="hidden" name="date" value="<?=e($date)?>"><div class="table-wrap"><table><tr><th>STT</th><th>Mã</th><th>Họ tên</th><th>Lớp</th><th>Trạng thái</th><th>Ghi chú</th></tr><?php foreach($students as $i=>$s):$st=$att[$s['id']]['status']??'Có mặt';?><tr><td><?=$i+1?></td><td><?=e($s['code'])?></td><td><?=e($s['full_name'])?></td><td><?=e($s['class_name'])?></td><td><select name="status[<?=$s['id']?>]"><option <?= $st==='Có mặt'?'selected':''?>>Có mặt</option><option <?= $st==='Vắng có phép'?'selected':''?>>Vắng có phép</option><option <?= $st==='Vắng không phép'?'selected':''?>>Vắng không phép</option><option <?= $st==='Đi muộn'?'selected':''?>>Đi muộn</option></select></td><td><input name="note_<?=$s['id']?>" value="<?=e($att[$s['id']]['note']??'')?>"></td></tr><?php endforeach;?></table></div><button class="btn primary">💾 Lưu điểm danh</button></form></section><?php layout_foot();exit;}
if($page==='assessments'){require_role(['admin','teacher']);layout_head('Đánh giá');$students=all('SELECT s.*,c.name class_name FROM students s LEFT JOIN classes c ON c.id=s.class_id ORDER BY s.full_name');$sid=(int)($_GET['student_id']??($students[0]['id']??0));$rows=all('SELECT a.*,sub.name subject_name FROM assessments a JOIN subjects sub ON sub.id=a.subject_id WHERE a.student_id=? ORDER BY a.id DESC',[$sid]);$subjects=all('SELECT * FROM subjects ORDER BY name');?><div class="page-title"><div><h1>Đánh giá học tập</h1><p>Nhập kết quả và nhận xét theo môn học, giai đoạn.</p></div></div><section class="card"><form class="search"><input type="hidden" name="page" value="assessments"><select name="student_id" onchange="this.form.submit()"><option value="">-- Chọn học sinh --</option><?php foreach($students as $s):?><option value="<?=$s['id']?>" <?=$sid===$s['id']?'selected':''?>><?=e($s['code'].' - '.$s['full_name'].' - '.($s['class_name']??''))?></option><?php endforeach;?></select></form><?php if($sid):?><form class="form-grid" method="post" action="index.php?page=save_assessment"><input type="hidden" name="student_id" value="<?=$sid?>"><label>Môn học<select name="subject_id"><?php foreach($subjects as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></label><label>Giai đoạn<select name="period"><option>Giữa học kỳ I</option><option>Cuối học kỳ I</option><option>Giữa học kỳ II</option><option>Cuối năm</option></select></label><label>Kết quả<input name="result" placeholder="Hoàn thành tốt / Hoàn thành / Chưa hoàn thành"></label><label class="fullrow">Nhận xét<textarea name="comment" rows="4"></textarea></label><div><button class="btn primary">Lưu đánh giá</button></div></form><?php endif;?></section><section class="card"><h2>Lịch sử đánh giá</h2><div class="table-wrap"><table><tr><th>Môn</th><th>Giai đoạn</th><th>Kết quả</th><th>Nhận xét</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['subject_name'])?></td><td><?=e($r['period'])?></td><td><?=e($r['result'])?></td><td><?=e($r['comment'])?></td></tr><?php endforeach;?></table></div></section><?php layout_foot();exit;}
